import {CommonModule} from '@angular/common';
import {PlayerVoteComponent} from '../../components/player-vote/player-vote.component';
import {ActivatedRoute} from '@angular/router';
import {TvzApiService} from '../../services/tvz-api.service';
import {Game} from '../../models/game.model';
import {Component, HostListener, Input, OnInit, OnDestroy} from '@angular/core';
import { Subject, timer, switchMap, takeUntil } from 'rxjs';
import {GamePlayerStat} from '../../models/gameplayerstats.model';
import {Player} from '../../models/player.model';
import {Top3ResultsComponent} from '../../components/top3-results/top3-results.component';
import {AuthService} from '../../services/auth.service';
import {GameViewComponent} from '../../components/game-view/game-view.component';
import {LoggerService} from '../../services/logger.service';


@Component({
  standalone: true,
  selector: 'app-game-detail',
  templateUrl: './game-detail-page.component.html',
  imports: [CommonModule, PlayerVoteComponent, Top3ResultsComponent, GameViewComponent],
})
export class GameDetailPageComponent implements OnInit, OnDestroy {
  game: Game | undefined;
  players: Player[] = [];
  homePlayers: Player[] = [];
  awayPlayers: Player[] = [];
  isVotingOpen = false;
  canAlwaysVote = true;
  statsLoaded = false;
  selectedVotes = new Map<number, number>();

  panelHeight = 196;
  minHeight = 60;          // deine Mindesthöhe (px) -> anpassen
  maxHeight = 640;          // optionaler Deckel; wird unten noch dynamisch aktualisiert
  compact = false;

  private resizing = false;
  private startY = 0;
  private startHeight = 0;
  private destroy$ = new Subject<void>();

  @Input() gameId: number | undefined;

  @HostListener('window:resize')
  onWindowResize() {
    this.maxHeight = Math.floor(window.innerHeight * 0.9);
    this.panelHeight = Math.min(this.panelHeight, this.maxHeight);
  }

  onResizeStart(ev: PointerEvent) {
    // Handle nur starten, wenn linke Taste / gültiger Pointer
    this.resizing = true;
    this.startY = ev.clientY;
    this.startHeight = this.panelHeight;

    // Pointer Capture, damit auch ausserhalb weiter bewegt werden kann
    (ev.target as Element).setPointerCapture?.(ev.pointerId);

    // Globale Listener aktivieren
    window.addEventListener('pointermove', this.onPointerMove, { passive: false });
    window.addEventListener('pointerup', this.onPointerUp, { passive: true });
  }

  // Arrow-Funktionen, damit removeEventListener funktioniert
  private onPointerMove = (ev: PointerEvent) => {
    if (!this.resizing) return;

    // Wir ziehen am oberen Rand eines bottom-fixed Panels:
    // nach oben bewegen -> Höhe grösser; nach unten -> kleiner
    const dy = this.startY - ev.clientY;
    let next = this.startHeight + dy;

    // Grenzen beachten
    next = Math.max(this.minHeight, Math.min(this.maxHeight, next));
    this.panelHeight = next;

    // Scrollen während Drag verhindern (bes. auf Mobile)
    ev.preventDefault();
  };

  private onPointerUp = (_ev: PointerEvent) => {
    this.resizing = false;
    window.removeEventListener('pointermove', this.onPointerMove);
    window.removeEventListener('pointerup', this.onPointerUp);
  };

  toggleCompact() {
    this.compact = !this.compact;
    this.panelHeight = this.compact ? this.minHeight : Math.max(this.panelHeight, 208);
  }

  constructor(private route: ActivatedRoute, private api: TvzApiService, private auth: AuthService, private log: LoggerService) {}

  ngOnInit() {
    if (this.gameId) {
      this.loadGameDetails();
    }
    this.route.params.subscribe(params => {
      if (params['id']) {
        this.gameId = parseInt(params['id']);
        this.loadGameDetails();
      }
    });
    this.auth.getUserVotes(this.gameId!).subscribe(votes => {
      this.selectedVotes = votes;
    })
  }

  loadGameDetails() {
    this.destroy$.next();
    this.startPolling();
    this.api.getGamePlayerStats(this.gameId!).subscribe(gameStats => {
      gameStats.forEach((gamePlayerStats: GamePlayerStat) => {
        const player: Player = {
          playerId: gamePlayerStats.playerId,
          playerName: gamePlayerStats.playerName,
          playerNumber: gamePlayerStats.dressNr > 0 ? `${gamePlayerStats.dressNr}` : null
        };
        if (gamePlayerStats.function !== "teamofficial") {
          this.players.push(player);
          if (gamePlayerStats.isHome) {
            this.homePlayers.push(player);
          } else {
            this.awayPlayers.push(player);
          }
        }
      });

      const playerSortFn = (a: Player, b: Player) => {
        const numA = parseInt(a.playerNumber ?? '999');
        const numB = parseInt(b.playerNumber ?? '999');
        if (numA !== numB) return numA - numB;
        return a.playerName.localeCompare(b.playerName);
      };

      this.homePlayers.sort(playerSortFn);
      this.awayPlayers.sort(playerSortFn);
      if (this.homePlayers.length === 0 && this.awayPlayers.length === 0) {
        this.compact = false;
      } else {
        this.compact = true;
      }
      this.toggleCompact();
      this.statsLoaded = true;
    })

  }

  private startPolling() {
    if (!this.gameId) {
      return;
    }

    timer(0, 10_000)
      .pipe(
        takeUntil(this.destroy$),
        switchMap(() => this.api.getGame(this.gameId!))
      )
      .subscribe(game => {
        this.game = game;
        // null  null null
        // 1 Spiel bereit null 1. Halbzeit (grün uhr
        // 1 Spiel bereit 0:00 1. Halbzeit
        // 2 Spiel läuft 31:34 2. Halbzeit (grün uhr
        // 3 Pause 30:00 2. Halbzeit
        // 4 Spiel beendet 60:00 2. Halbzeit
        // 5 Spiel läuft 22:18 1. Halbzeit
        // 5 Spiel läuft 30:00 1. Halbzeit
        if (game.ltGameStatusId && game.ltGameStatusId > 1 && game.ltGameStatusId != 4) {
          this.isVotingOpen = true;
        } else {
          this.isVotingOpen = false;
        }
        this.isVotingOpen = this.isVotingOpen || this.canAlwaysVote;
        this.log.log(`game status: ${game.gameStatusId} (${game.gameStatus}), lt: ${game.ltGameStatusId} (${game.ltGameStatus}), voting: ${this.isVotingOpen}`);

        if (game.ltGameStatusId === 4) {
          this.destroy$.next();
        }
      });
  }

  ngOnDestroy() {
    this.destroy$.next();
    this.destroy$.complete();
  }
}
