import {Component, Input, OnDestroy, OnInit} from '@angular/core';
import {CommonModule} from '@angular/common';
import {FormsModule} from '@angular/forms';
import {Player} from '../../models/player.model';
import {VoteBarComponent} from '../vote-bar/vote-bar.component';
import {GraphQLWsService} from '../../services/graphql-ws.service';
import {Subscription} from 'rxjs';
import {LoggerService} from '../../services/logger.service';

@Component({
  standalone: true,
  selector: 'app-top3-results',
  templateUrl: './top3-results.component.html',
  imports: [CommonModule, FormsModule, VoteBarComponent],
})
export class Top3ResultsComponent implements OnInit, OnDestroy {
  @Input() gameId = 0;
  @Input() teamId = 0;
  @Input() teamName = '';
  @Input() players: Player[] = [];

  votes:any[] = [];
  totalVotes: number = 0;

  private playerMap = new Map<number, Player>();
  private sub?: Subscription;

  constructor(private gQLSubscription: GraphQLWsService, private log: LoggerService) {}

  ngOnInit() {
    this.log.log(`create ${this.gameId} ${this.teamId}`);
    this.playerMap = new Map(this.players.map(p => [p.playerId, p]));
    this.loadTop3Sub();
  }

  ngOnDestroy() {
    this.sub?.unsubscribe();
    this.log.log(`destroy ${this.gameId} ${this.teamId}`);
  }

  loadTop3Sub() {
    this.sub = this.gQLSubscription.subscribeVoteSummary(this.gameId, this.teamId).subscribe({
      next: (data) => {
        if (data && data.voteSummary) {
          this.votes = this.resolvePlayerNames(data.voteSummary)
        }
      },
      error: (err) => this.log.error(err)
    })
  }

  private resolvePlayerNames(votes: any[]): any[] {
    const result =  votes.map(vote => ({
      ...vote,
      playerObj: this.playerMap.get(vote.player),
    })).sort((a: any, b: any) => b.totalWeight - a.totalWeight)
    this.totalVotes = votes.reduce((sum, vote) => sum + vote.totalWeight, 0);
    return result.slice(0, 3);
  }
}
