import {Component, Input} from '@angular/core';
import {CommonModule} from '@angular/common';
import {FormsModule} from '@angular/forms';
import {Player} from '../../models/player.model';
import {AuthService} from '../../services/auth.service';
import {ToastService} from '../../services/toast.service';
import {LoggerService} from '../../services/logger.service';

@Component({
  standalone: true,
  selector: 'app-player-vote',
  templateUrl: './player-vote.component.html',
  imports: [CommonModule, FormsModule],
})
export class PlayerVoteComponent {
  @Input() players: Player[] = [];
  @Input() gameId: number | undefined;
  @Input() teamId: number | undefined;
  @Input() selectedVotes = new Map<number, number>();

  constructor(private auth: AuthService, private toast: ToastService, private log: LoggerService) {
  }

  vote(player: Player) {
    const currentVote = this.selectedVotes.get(this.teamId!)
    if (currentVote === player.playerId) {
      this.auth.removeVote(this.gameId!, this.teamId!, player.playerId).subscribe({
        error: (err) => this.log.error('Fehler beim Entfernen:', err),
      })
      this.selectedVotes.delete(this.teamId!);
    } else {
      this.selectedVotes.set(this.teamId!, player.playerId)
      this.auth.saveVote(this.gameId!,  this.teamId!, player.playerId).subscribe({
        next: () => this.toast.add('Stimme registriert', 'Deine Stimmer wurde mit dem Faktor registriert', "info", 1000),
        error: (err) => this.log.error('Fehler beim Entfernen:', err),
      })
    }
  }
}
