import { Injectable } from '@angular/core';
import { Observable, Subject, Subscription } from 'rxjs';
import {LoggerService} from './logger.service';
import {environment} from '../../environments/environment';

interface ActiveStream {
  subject: Subject<any>;
  subscribers: number;
}

@Injectable({ providedIn: 'root' })
export class GraphQLWsService {
  private ws?: WebSocket;
  private streams = new Map<string, ActiveStream>();
  private isConnected = false;

  constructor(private log: LoggerService) {
    this.log.log('[GraphQL WsService]' + this);
    this.connect();
  }

  private connect() {
    this.ws = new WebSocket(`ws://${environment.wsHost}/graphql`, 'graphql-transport-ws');

    this.ws.onopen = () => {
      this.log.log('✅ WebSocket verbunden');
      this.ws!.send(JSON.stringify({ type: 'connection_init', payload: {} }));
      this.isConnected = true;
    };

    this.ws.onmessage = (event) => {
      const msg = JSON.parse(event.data);
      if (msg.type === 'next' && this.streams.has(msg.id)) {
        this.streams.get(msg.id)!.subject.next(msg.payload.data);
      }
      if (msg.type === 'complete' && this.streams.has(msg.id)) {
        this.streams.get(msg.id)!.subject.complete();
        this.streams.delete(msg.id);
      }
    };

    this.ws.onclose = (ev) => {
      this.log.warn('🔌 WebSocket geschlossen:', ev.reason);
      this.isConnected = false;

      // Verhindere mehrfachen Reconnect
      if (this.ws?.readyState !== WebSocket.OPEN) {
        setTimeout(() => this.connect(), 2000);
      }
    };
  }

  private sendSubscribe(gameId: number, teamId: number) {
    const id = `game-${gameId}-${teamId}`;
    if (!this.streams.has(id)) return; // Sicherheitsprüfung

    const stream = this.streams.get(id)!;
    if ((stream as any).subscribedOnce) {
      this.log.warn(`⚠️ Subscription für ${id} existiert bereits`);
      return;
    }
    const msg = {
      id,
      type: 'subscribe',
      payload: {
        query: `
          subscription($game: Int!, $team: Int!) {
            voteSummary(game: $game, team: $team) {
              game
              team
              player
              totalWeight
            }
          }
        `,
        variables: { game: gameId, team: teamId }
      }
    };
    this.ws?.send(JSON.stringify(msg));
    this.log.log(`📡 Subscribed to ${id}`);
  }

  subscribeVoteSummary(gameId: number, teamId: number): Observable<any> {
    const id = `game-${gameId}-${teamId}`;
    let stream = this.streams.get(id);

    if (!stream) {
      const subject = new Subject<any>();
      stream = { subject, subscribers: 0 };
      this.streams.set(id, stream);

      let subscribed = false;

      const doSubscribe = () => {
        if (!subscribed && this.isConnected) {
          this.sendSubscribe(gameId, teamId);
          subscribed = true;
        }
      };

      if (this.isConnected) {
        doSubscribe();
      } else {
        const wait = setInterval(() => {
          if (this.isConnected) {
            doSubscribe();
            clearInterval(wait);
          }
        }, 200);
      }
    }

    stream.subscribers++;

    return new Observable((observer) => {
      const sub: Subscription = stream!.subject.subscribe(observer);

      return () => {
        sub.unsubscribe();
        stream!.subscribers--;
        this.log.log(`👋 Unsubscribed from ${id}, left: ${stream!.subscribers}`);
        if (stream!.subscribers <= 0) {
          this.ws?.send(JSON.stringify({ id, type: 'complete' }));
          this.streams.delete(id);
          this.log.log(`🧹 Stream ${id} entfernt`);
        }
      };
    });
  }
}
